    interpolate(slideOutSpring, [0, 1], [0, targetX - offscreenX]);

  // 2. Swinging Door Effect (Rotate Y)
  const swingStartFrame = entranceStartFrame + 5;
  const swingSpring = spring({
    frame: Math.max(0, frame - swingStartFrame),
    fps,
    config: { damping: 5, stiffness: 45 }, // Low damping creates the back-and-forth swing
  });

